import math

def newman_prime(n):
    """
    Returns the nth newman–shanks–williams prime number.

    Parameters:
    n (int): The position of the newman–shanks–williams prime to return.

    Returns:
    int: The nth newman–shanks–williams prime number.
    """
    def is_prime(num):
        if num < 2:
            return False
        for i in range(2, int(math.sqrt(num)) + 1):
            if num % i == 0:
                return False
        return True

    def newman_shanks_williams(n):
        if n == 1:
            return 2
        elif n == 2:
            return 7
        elif n == 3:
            return 7
        elif n == 4:
            return 17
        elif n == 5:
            return 41
        else:
            x = 2
            for _ in range(n - 5):
                x = x * x - 2
            return x

    return newman_shanks_williams(n)
